// broken_discount.rs - 의도적 로직 버그 (Self-Healing 테스트용)
// 버그: 할인율 계산에서 100 대신 10으로 나눔 → 10배 과다 할인

fn calculate_discount(price: f64, discount_percent: f64) -> f64 {
    // 버그: /10.0 이어야 하는 게 아니라 /100.0 이어야 함
    // 30% 할인 → price * 0.3 이어야 하는데 price * 3.0 이 됨
    price - (price * discount_percent / 10.0)
}

fn apply_coupon(price: f64, coupon_code: &str) -> f64 {
    match coupon_code {
        "SAVE10" => calculate_discount(price, 10.0),
        "SAVE20" => calculate_discount(price, 20.0),
        "SAVE30" => calculate_discount(price, 30.0),
        _ => price,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_10_percent_discount() {
        // 100원의 10% 할인 → 90원이어야 함
        let result = apply_coupon(100.0, "SAVE10");
        assert_eq!(result, 90.0);
    }

    #[test]
    fn test_30_percent_discount() {
        // 100원의 30% 할인 → 70원이어야 함
        let result = apply_coupon(100.0, "SAVE30");
        assert_eq!(result, 70.0);
    }

    #[test]
    fn test_no_coupon() {
        let result = apply_coupon(100.0, "INVALID");
        assert_eq!(result, 100.0);
    }
}

