// ============================================================
// webhook.fl - HTTP Webhook 서버
// raw TCP 소켓 - 외부 라이브러리 없음
// POST /webhook/push, /webhook/ci, /webhook/manual
// ============================================================

struct WebhookServer {
  host: string,
  port: i32,
  cfg: AgentConfig
}

struct HttpRequest {
  method: string,
  path: string,
  headers: array,     // "Key: Value" 문자열 배열
  body: string,
  client_ip: string
}

struct HttpResponse {
  status: i32,
  status_text: string,
  body: string
}

// ==================== 서버 시작 ====================

fn webhook_server_start(cfg: AgentConfig) -> Result<void, string>
  intent "Webhook HTTP 서버 메인 루프"
  do
    print("🚀 Self-Healing Agent Webhook Server")
    print("   주소: " + cfg.webhook_host + ":" + int_to_str(cfg.webhook_port))
