    LoadInt(i64),
    LoadFloat(f64),
    LoadLocal(u32),
    StoreLocal(u32),
    Add,
    Sub,
    Mul,
    Div,
    Cmp(CmpOp),
    Jump(i32),          // relative offset
    JumpIfTrue(i32),
    JumpIfFalse(i32),
    Call(u32),          // function id
    Return,
    Nop,
}

enum CmpOp {
    Lt, Le, Eq, Ne, Ge, Gt,
}

struct JitConfig {
    trace_threshold: u32,       // hot loop threshold
