# ================================================================
# FreeLang v4 Core - x86-64 Machine Code Emitter
# Encodes JIT instruction objects into actual x86-64 byte sequences
# ABI: System V AMD64 (Linux)
# ================================================================

# ---- Byte Buffer ----

fn emit_buf_new() -> any {
  return { "bytes": [], "pos": 0, "labels": {}, "patches": [] }
}

fn emit_byte(buf: any, b: i32) -> any {
  push(buf["bytes"], b)
  buf["pos"] = buf["pos"] + 1
  return buf
}

fn emit_bytes(buf: any, bs: array) -> any {
  i = 0
  while i < length(bs) {
    buf = emit_byte(buf, bs[i])
    i = i + 1
  }
  return buf
}

fn emit_i32(buf: any, v: i32) -> any {
  buf = emit_byte(buf, v & 0xFF)
  buf = emit_byte(buf, (v >> 8)  & 0xFF)
  buf = emit_byte(buf, (v >> 16) & 0xFF)
  buf = emit_byte(buf, (v >> 24) & 0xFF)
  return buf
}

fn emit_i64(buf: any, v: i64) -> any {
  buf = emit_byte(buf, v & 0xFF)
  buf = emit_byte(buf, (v >> 8)  & 0xFF)
  buf = emit_byte(buf, (v >> 16) & 0xFF)
  buf = emit_byte(buf, (v >> 24) & 0xFF)
  buf = emit_byte(buf, (v >> 32) & 0xFF)
  buf = emit_byte(buf, (v >> 40) & 0xFF)
  buf = emit_byte(buf, (v >> 48) & 0xFF)
  buf = emit_byte(buf, (v >> 56) & 0xFF)
  return buf
}

# ---- Register Encoding ----
# x86-64 register numbers (3-bit rm/reg field)
REG_RAX = 0
REG_RCX = 1
REG_RDX = 2
REG_RBX = 3
REG_RSP = 4
REG_RBP = 5
REG_RSI = 6
REG_RDI = 7
REG_R8  = 8
REG_R9  = 9
REG_R10 = 10
REG_R11 = 11
REG_R12 = 12
REG_R13 = 13
REG_R14 = 14
REG_R15 = 15

fn reg_num(name: string) -> i32 {
  match name {
    "rax" => { return REG_RAX },
    "rcx" => { return REG_RCX },
    "rdx" => { return REG_RDX },
    "rbx" => { return REG_RBX },
    "rsp" => { return REG_RSP },
    "rbp" => { return REG_RBP },
    "rsi" => { return REG_RSI },
    "rdi" => { return REG_RDI },
    "r8"  => { return REG_R8 },
    "r9"  => { return REG_R9 },
    "r10" => { return REG_R10 },
    "r11" => { return REG_R11 },
    "r12" => { return REG_R12 },
    "r13" => { return REG_R13 },
    "r14" => { return REG_R14 },
    "r15" => { return REG_R15 },
    _ => { return REG_RAX }
  }
}

fn reg_needs_rex(r: i32) -> bool {
  return r >= 8
}

# REX prefix: 0100 WRXB
# W=1: 64-bit operand
# R: ModRM.reg extension
# X: SIB.index extension
# B: ModRM.rm extension
fn rex_prefix(w: bool, r: bool, x: bool, b: bool) -> i32 {
  v = 0x40
  if w { v = v | 0x08 }
  if r { v = v | 0x04 }
  if x { v = v | 0x02 }
  if b { v = v | 0x01 }
  return v
}

fn modrm(mod: i32, reg: i32, rm: i32) -> i32 {
  return ((mod & 3) << 6) | ((reg & 7) << 3) | (rm & 7)
}

# ---- Function Prologue / Epilogue ----

fn emit_prologue(buf: any) -> any {
  # push rbp
  buf = emit_byte(buf, 0x55)
  # mov rbp, rsp  →  REX.W 0x89 ModRM(11, rsp, rbp)
  buf = emit_byte(buf, rex_prefix(true, false, false, false))
  buf = emit_byte(buf, 0x89)
  buf = emit_byte(buf, modrm(3, REG_RSP, REG_RBP))
  return buf
}

fn emit_epilogue(buf: any) -> any {
  # pop rbp
  buf = emit_byte(buf, 0x5D)
  # ret
  buf = emit_byte(buf, 0xC3)
  return buf
}

fn emit_alloc_stack(buf: any, bytes: i32) -> any {
  # sub rsp, imm32
  buf = emit_byte(buf, rex_prefix(true, false, false, false))
  buf = emit_byte(buf, 0x81)
  buf = emit_byte(buf, modrm(3, 5, REG_RSP))  # /5 = SUB
  buf = emit_i32(buf, bytes)
  return buf
}

# ---- MOV instructions ----

fn emit_mov_rr(buf: any, dst: i32, src: i32) -> any {
  # REX.W MOV reg, reg/m64
  rex_r = reg_needs_rex(src)
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x89)
  buf = emit_byte(buf, modrm(3, src & 7, dst & 7))
  return buf
}

fn emit_mov_ri64(buf: any, dst: i32, imm: i64) -> any {
  # REX.W MOVABS reg, imm64
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0xB8 | (dst & 7))
  buf = emit_i64(buf, imm)
  return buf
}

fn emit_mov_ri32(buf: any, dst: i32, imm: i32) -> any {
  # REX.W MOV reg, sign-extended imm32
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0xC7)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))
  buf = emit_i32(buf, imm)
  return buf
}

fn emit_mov_mem_r(buf: any, base: i32, offset: i32, src: i32) -> any {
  # MOV [base + offset], src
  rex_r = reg_needs_rex(src)
  rex_b = reg_needs_rex(base)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x89)
  buf = emit_byte(buf, modrm(2, src & 7, base & 7))
  buf = emit_i32(buf, offset)
  return buf
}

fn emit_mov_r_mem(buf: any, dst: i32, base: i32, offset: i32) -> any {
  # MOV dst, [base + offset]
  rex_r = reg_needs_rex(dst)
  rex_b = reg_needs_rex(base)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x8B)
  buf = emit_byte(buf, modrm(2, dst & 7, base & 7))
  buf = emit_i32(buf, offset)
  return buf
}

# ---- Arithmetic ----

fn emit_add_rr(buf: any, dst: i32, src: i32) -> any {
  rex_r = reg_needs_rex(src)
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x01)
  buf = emit_byte(buf, modrm(3, src & 7, dst & 7))
  return buf
}

fn emit_add_ri32(buf: any, dst: i32, imm: i32) -> any {
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0x81)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))  # /0 = ADD
  buf = emit_i32(buf, imm)
  return buf
}

fn emit_sub_rr(buf: any, dst: i32, src: i32) -> any {
  rex_r = reg_needs_rex(src)
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x29)
  buf = emit_byte(buf, modrm(3, src & 7, dst & 7))
  return buf
}

fn emit_sub_ri32(buf: any, dst: i32, imm: i32) -> any {
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0x81)
  buf = emit_byte(buf, modrm(3, 5, dst & 7))  # /5 = SUB
  buf = emit_i32(buf, imm)
  return buf
}

fn emit_imul_rr(buf: any, dst: i32, src: i32) -> any {
  # IMUL dst, src  (dst = dst * src)
  rex_r = reg_needs_rex(dst)
  rex_b = reg_needs_rex(src)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0xAF)
  buf = emit_byte(buf, modrm(3, dst & 7, src & 7))
  return buf
}

fn emit_idiv_r(buf: any, divisor: i32) -> any {
  # CQO (sign-extend rax to rdx:rax)
  buf = emit_byte(buf, rex_prefix(true, false, false, false))
  buf = emit_byte(buf, 0x99)
  # IDIV divisor
  rex_b = reg_needs_rex(divisor)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0xF7)
  buf = emit_byte(buf, modrm(3, 7, divisor & 7))  # /7 = IDIV
  return buf
}

fn emit_xor_rr(buf: any, dst: i32, src: i32) -> any {
  rex_r = reg_needs_rex(src)
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x31)
  buf = emit_byte(buf, modrm(3, src & 7, dst & 7))
  return buf
}

fn emit_and_rr(buf: any, dst: i32, src: i32) -> any {
  rex_r = reg_needs_rex(src)
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x21)
  buf = emit_byte(buf, modrm(3, src & 7, dst & 7))
  return buf
}

fn emit_or_rr(buf: any, dst: i32, src: i32) -> any {
  rex_r = reg_needs_rex(src)
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x09)
  buf = emit_byte(buf, modrm(3, src & 7, dst & 7))
  return buf
}

fn emit_neg_r(buf: any, dst: i32) -> any {
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0xF7)
  buf = emit_byte(buf, modrm(3, 3, dst & 7))  # /3 = NEG
  return buf
}

fn emit_shl_ri(buf: any, dst: i32, imm: i32) -> any {
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0xC1)
  buf = emit_byte(buf, modrm(3, 4, dst & 7))  # /4 = SHL
  buf = emit_byte(buf, imm & 0x3F)
  return buf
}

fn emit_shr_ri(buf: any, dst: i32, imm: i32) -> any {
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0xC1)
  buf = emit_byte(buf, modrm(3, 5, dst & 7))  # /5 = SHR
  buf = emit_byte(buf, imm & 0x3F)
  return buf
}

# ---- Comparison & Conditionals ----

fn emit_cmp_rr(buf: any, a: i32, b: i32) -> any {
  rex_r = reg_needs_rex(b)
  rex_b = reg_needs_rex(a)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x39)
  buf = emit_byte(buf, modrm(3, b & 7, a & 7))
  return buf
}

fn emit_cmp_ri32(buf: any, dst: i32, imm: i32) -> any {
  rex_b = reg_needs_rex(dst)
  buf = emit_byte(buf, rex_prefix(true, false, false, rex_b))
  buf = emit_byte(buf, 0x81)
  buf = emit_byte(buf, modrm(3, 7, dst & 7))  # /7 = CMP
  buf = emit_i32(buf, imm)
  return buf
}

fn emit_test_rr(buf: any, a: i32, b: i32) -> any {
  rex_r = reg_needs_rex(b)
  rex_b = reg_needs_rex(a)
  buf = emit_byte(buf, rex_prefix(true, rex_r, false, rex_b))
  buf = emit_byte(buf, 0x85)
  buf = emit_byte(buf, modrm(3, b & 7, a & 7))
  return buf
}

# SETcc: set byte based on condition code
fn emit_sete(buf: any, dst: i32) -> any {
  rex_b = reg_needs_rex(dst)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x94)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))
  return buf
}

fn emit_setne(buf: any, dst: i32) -> any {
  rex_b = reg_needs_rex(dst)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x95)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))
  return buf
}

fn emit_setl(buf: any, dst: i32) -> any {
  rex_b = reg_needs_rex(dst)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x9C)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))
  return buf
}

fn emit_setle(buf: any, dst: i32) -> any {
  rex_b = reg_needs_rex(dst)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x9E)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))
  return buf
}

fn emit_setg(buf: any, dst: i32) -> any {
  rex_b = reg_needs_rex(dst)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x9F)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))
  return buf
}

fn emit_setge(buf: any, dst: i32) -> any {
  rex_b = reg_needs_rex(dst)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x9D)
  buf = emit_byte(buf, modrm(3, 0, dst & 7))
  return buf
}

# ---- Jumps ----

fn emit_label(buf: any, name: string) -> any {
  buf["labels"][name] = buf["pos"]
  return buf
}

fn emit_jmp_rel32(buf: any, label: string) -> any {
  # JMP rel32: E9 <offset32>
  buf = emit_byte(buf, 0xE9)
  # record patch location
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "jmp" })
  buf = emit_i32(buf, 0)  # placeholder
  return buf
}

fn emit_jz_rel32(buf: any, label: string) -> any {
  # JZ rel32: 0F 84 <offset32>
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x84)
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "jz" })
  buf = emit_i32(buf, 0)
  return buf
}

fn emit_jnz_rel32(buf: any, label: string) -> any {
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x85)
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "jnz" })
  buf = emit_i32(buf, 0)
  return buf
}

fn emit_jl_rel32(buf: any, label: string) -> any {
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x8C)
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "jl" })
  buf = emit_i32(buf, 0)
  return buf
}

fn emit_jge_rel32(buf: any, label: string) -> any {
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x8D)
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "jge" })
  buf = emit_i32(buf, 0)
  return buf
}

fn emit_jle_rel32(buf: any, label: string) -> any {
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x8E)
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "jle" })
  buf = emit_i32(buf, 0)
  return buf
}

fn emit_jg_rel32(buf: any, label: string) -> any {
  buf = emit_byte(buf, 0x0F)
  buf = emit_byte(buf, 0x8F)
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "jg" })
  buf = emit_i32(buf, 0)
  return buf
}

# ---- Call / Return ----

fn emit_call_r(buf: any, fn_reg: i32) -> any {
  rex_b = reg_needs_rex(fn_reg)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0xFF)
  buf = emit_byte(buf, modrm(3, 2, fn_reg & 7))  # /2 = CALL
  return buf
}

fn emit_call_rel32(buf: any, label: string) -> any {
  buf = emit_byte(buf, 0xE8)
  push(buf["patches"], { "pos": buf["pos"], "label": label, "type": "call" })
  buf = emit_i32(buf, 0)
  return buf
}

fn emit_ret(buf: any) -> any {
  buf = emit_byte(buf, 0xC3)
  return buf
}

# ---- Stack Operations ----

fn emit_push_r(buf: any, reg: i32) -> any {
  rex_b = reg_needs_rex(reg)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x50 | (reg & 7))
  return buf
}

fn emit_pop_r(buf: any, reg: i32) -> any {
  rex_b = reg_needs_rex(reg)
  if rex_b { buf = emit_byte(buf, rex_prefix(false, false, false, rex_b)) }
  buf = emit_byte(buf, 0x58 | (reg & 7))
  return buf
}

# ---- Label Patching ----

fn emit_patch_labels(buf: any) -> any {
  i = 0
  while i < length(buf["patches"]) {
    patch = buf["patches"][i]
    label_pos = buf["labels"][patch["label"]]
    if label_pos != nil {
      # offset = target - (patch_pos + 4)
      # patch_pos is where the 4-byte immediate starts
      offset = label_pos - (patch["pos"] + 4)
      # Write offset into bytes[patch["pos"]] .. bytes[patch["pos"]+3]
      p = patch["pos"]
      buf["bytes"][p]     = offset & 0xFF
      buf["bytes"][p + 1] = (offset >> 8)  & 0xFF
      buf["bytes"][p + 2] = (offset >> 16) & 0xFF
      buf["bytes"][p + 3] = (offset >> 24) & 0xFF
    }
    i = i + 1
  }
  return buf
}

# ---- Native Instruction -> Bytes ----

fn encode_native_instr(buf: any, instr: any) -> any {
  t = instr["type"]
  match t {
    "label" => {
      buf = emit_label(buf, instr["name"])
    },
    "prologue" => {
      buf = emit_prologue(buf)
    },
    "epilogue" => {
      buf = emit_epilogue(buf)
    },
    "alloc_stack" => {
      buf = emit_alloc_stack(buf, instr["size"])
    },
    "mov" => {
      dst = instr["dest"]
      src = instr["src"]
      imm = instr["imm"]
      if imm != nil {
        buf = emit_mov_ri32(buf, reg_num(dst), imm)
      } else if src != nil {
        buf = emit_mov_rr(buf, reg_num(dst), reg_num(src))
      }
    },
    "mov64" => {
      buf = emit_mov_ri64(buf, reg_num(instr["dest"]), instr["imm"])
    },
    "load" => {
      buf = emit_mov_r_mem(buf, reg_num(instr["dest"]), reg_num(instr["base"]), instr["offset"])
    },
    "store" => {
      buf = emit_mov_mem_r(buf, reg_num(instr["base"]), instr["offset"], reg_num(instr["src"]))
    },
    "add" => {
      buf = emit_add_rr(buf, reg_num(instr["dest"]), reg_num(instr["src"]))
    },
    "add_imm" => {
      buf = emit_add_ri32(buf, reg_num(instr["dest"]), instr["imm"])
    },
    "sub" => {
      buf = emit_sub_rr(buf, reg_num(instr["dest"]), reg_num(instr["src"]))
    },
    "sub_imm" => {
      buf = emit_sub_ri32(buf, reg_num(instr["dest"]), instr["imm"])
    },
    "imul" => {
      buf = emit_imul_rr(buf, reg_num(instr["dest"]), reg_num(instr["src"]))
    },
    "idiv" => {
      buf = emit_idiv_r(buf, reg_num(instr["src"]))
    },
    "xor" => {
      buf = emit_xor_rr(buf, reg_num(instr["dest"]), reg_num(instr["src"]))
    },
    "and" => {
      buf = emit_and_rr(buf, reg_num(instr["dest"]), reg_num(instr["src"]))
    },
    "or" => {
      buf = emit_or_rr(buf, reg_num(instr["dest"]), reg_num(instr["src"]))
    },
    "neg" => {
      buf = emit_neg_r(buf, reg_num(instr["dest"]))
    },
    "shl" => {
      buf = emit_shl_ri(buf, reg_num(instr["dest"]), instr["imm"])
    },
    "shr" => {
      buf = emit_shr_ri(buf, reg_num(instr["dest"]), instr["imm"])
    },
    "cmp" => {
      buf = emit_cmp_rr(buf, reg_num(instr["src1"]), reg_num(instr["src2"]))
    },
    "cmp_imm" => {
      buf = emit_cmp_ri32(buf, reg_num(instr["src1"]), instr["imm"])
    },
    "test" => {
      r = reg_num(instr["src"])
      buf = emit_test_rr(buf, r, r)
    },
    "sete"  => { buf = emit_sete(buf,  reg_num(instr["dest"])) },
    "setne" => { buf = emit_setne(buf, reg_num(instr["dest"])) },
    "setl"  => { buf = emit_setl(buf,  reg_num(instr["dest"])) },
    "setle" => { buf = emit_setle(buf, reg_num(instr["dest"])) },
    "setg"  => { buf = emit_setg(buf,  reg_num(instr["dest"])) },
    "setge" => { buf = emit_setge(buf, reg_num(instr["dest"])) },
    "jmp"   => { buf = emit_jmp_rel32(buf,  instr["label"]) },
    "jz"    => { buf = emit_jz_rel32(buf,   instr["label"]) },
    "jnz"   => { buf = emit_jnz_rel32(buf,  instr["label"]) },
    "jl"    => { buf = emit_jl_rel32(buf,   instr["label"]) },
    "jge"   => { buf = emit_jge_rel32(buf,  instr["label"]) },
    "jle"   => { buf = emit_jle_rel32(buf,  instr["label"]) },
    "jg"    => { buf = emit_jg_rel32(buf,   instr["label"]) },
    "call"  => { buf = emit_call_rel32(buf,  instr["target"]) },
    "call_r" => { buf = emit_call_r(buf, reg_num(instr["fn_reg"])) },
    "ret"   => { buf = emit_ret(buf) },
    "push"  => { buf = emit_push_r(buf, reg_num(instr["src"])) },
    "pop"   => { buf = emit_pop_r(buf, reg_num(instr["dest"])) },
    "nop"   => { buf = emit_byte(buf, 0x90) },
    _ => {
      # unknown instruction - emit NOP
      buf = emit_byte(buf, 0x90)
    }
  }
  return buf
}

# ---- Top-level: Assemble native code list to bytes ----

fn x86_assemble(native_code: array) -> any {
  buf = emit_buf_new()

  # First pass: collect labels
  # (labels emitted inline during first pass)

  # Single pass emit (labels recorded as we go, backward jumps patched)
  i = 0
  while i < length(native_code) {
    buf = encode_native_instr(buf, native_code[i])
    i = i + 1
  }

  # Patch forward jumps
  buf = emit_patch_labels(buf)

  return {
    "bytes": buf["bytes"],
    "size": buf["pos"],
    "labels": buf["labels"],
    "unpatched": length(buf["patches"]) - dict_len(buf["labels"])
  }
}

# ---- Disassembler (debug) ----

fn x86_disasm_byte_range(bytes: array, start: i32, end: i32) -> string {
  out = ""
  i = start
  while i < end and i < length(bytes) {
    b = bytes[i]
    out = out + hex_byte(b) + " "
    i = i + 1
  }
  return out
}

fn hex_byte(b: i32) -> string {
  hex = "0123456789ABCDEF"
  hi = (b >> 4) & 0xF
  lo = b & 0xF
  return char_at(hex, hi) + char_at(hex, lo)
}

fn x86_dump(result: any) -> string {
  out = "=== x86-64 Machine Code ===\n"
  out = out + "Size: " + to_string(result["size"]) + " bytes\n"
  out = out + "Labels: " + to_string(dict_len(result["labels"])) + "\n"
  out = out + "Bytes: " + x86_disasm_byte_range(result["bytes"], 0, result["size"]) + "\n"
  return out
}

# ---- Code Cache Management ----

fn code_cache_new(max_bytes: i32) -> any {
  return {
    "entries": {},       # fn_name -> { bytes, size, tier, hot_count }
    "total_bytes": 0,
    "max_bytes": max_bytes,
    "evictions": 0,
    "hits": 0,
    "misses": 0
  }
}

fn code_cache_put(cache: any, fn_name: string, bytes: array, tier: i32) -> any {
  size = length(bytes)

  # Evict LRU entries if over limit
  while cache["total_bytes"] + size > cache["max_bytes"] and dict_len(cache["entries"]) > 0 {
    evict_key = cache_find_lru(cache)
    if evict_key == nil { break }
    old = cache["entries"][evict_key]
    cache["total_bytes"] = cache["total_bytes"] - old["size"]
    dict_delete(cache["entries"], evict_key)
    cache["evictions"] = cache["evictions"] + 1
  }

  cache["entries"][fn_name] = {
    "bytes": bytes,
    "size": size,
    "tier": tier,
    "hot_count": 0,
    "last_used": time_now()
  }
  cache["total_bytes"] = cache["total_bytes"] + size
  return cache
}

fn code_cache_get(cache: any, fn_name: string) -> any {
  entry = cache["entries"][fn_name]
  if entry == nil {
    cache["misses"] = cache["misses"] + 1
    return nil
  }
  entry["hot_count"] = entry["hot_count"] + 1
  entry["last_used"] = time_now()
  cache["hits"] = cache["hits"] + 1
  return entry["bytes"]
}

fn cache_find_lru(cache: any) -> string {
  oldest_time = 9999999999999
  oldest_key = nil
  keys = dict_keys(cache["entries"])
  i = 0
  while i < length(keys) {
    entry = cache["entries"][keys[i]]
    if entry["last_used"] < oldest_time and entry["tier"] < 2 {
      oldest_time = entry["last_used"]
      oldest_key = keys[i]
    }
    i = i + 1
  }
  return oldest_key
}

fn code_cache_stats(cache: any) -> any {
  total_req = cache["hits"] + cache["misses"]
  hit_rate = 0.0
  if total_req > 0 { hit_rate = (cache["hits"] * 100.0) / total_req }
  return {
    "entries": dict_len(cache["entries"]),
    "total_bytes": cache["total_bytes"],
    "max_bytes": cache["max_bytes"],
    "utilization_pct": (cache["total_bytes"] * 100) / cache["max_bytes"],
    "hits": cache["hits"],
    "misses": cache["misses"],
    "hit_rate_pct": hit_rate,
    "evictions": cache["evictions"]
  }
}

# ---- Integration: JIT Compile + Assemble ----

fn jit_emit_function(jit: any, fn_name: string, cache: any) -> any {
  compiled = jit["compiled_functions"][fn_name]
  if compiled == nil {
    return { "success": false, "error": "function not compiled: " + fn_name }
  }

  result = x86_assemble(compiled)
  if result["size"] == 0 {
    return { "success": false, "error": "empty code for: " + fn_name }
  }

  tier = JIT_TIER_BASELINE
  profile = jit["profiles"][fn_name]
  if profile != nil { tier = profile["tier"] }

  cache = code_cache_put(cache, fn_name, result["bytes"], tier)

  return {
    "success": true,
    "fn_name": fn_name,
    "bytes": result["bytes"],
    "size": result["size"],
    "labels": result["labels"],
    "cache": cache
  }
}

fn x86_emitter_report(cache: any) -> string {
  stats = code_cache_stats(cache)
  out = "=== x86 Emitter Report ===\n"
  out = out + "Cache entries:   " + to_string(stats["entries"]) + "\n"
  out = out + "Cache bytes:     " + to_string(stats["total_bytes"]) + " / " + to_string(stats["max_bytes"]) + "\n"
  out = out + "Utilization:     " + to_string(stats["utilization_pct"]) + "%\n"
  out = out + "Hit rate:        " + to_string(stats["hit_rate_pct"]) + "%\n"
  out = out + "Evictions:       " + to_string(stats["evictions"]) + "\n"
  return out
}

