# ================================================================
# FreeLang v4 Core - Macro System
# Hygienic macros with pattern matching + token substitution
# Supports: declarative macros (macro_rules!) + procedural macros
# ================================================================

# ---- Macro Token Types ----

MTOK_EXPR     = "expr"       # matches any expression
MTOK_STMT     = "stmt"       # matches a statement
MTOK_TYPE     = "ty"         # matches a type
MTOK_IDENT    = "ident"      # matches an identifier
MTOK_LITERAL  = "literal"    # matches a literal (int/str/bool)
MTOK_BLOCK    = "block"      # matches a { ... } block
MTOK_PATH     = "path"       # matches a :: separated path
MTOK_META     = "meta"       # matches a meta item
MTOK_PAT      = "pat"        # matches a pattern
MTOK_TT       = "tt"         # matches any single token tree
MTOK_REPEAT   = "repeat"     # $(...)*  or  $(...)+  or  $(...)?

# ---- Macro Definition ----

fn macro_def_new(name: string) -> any {
  return {
    "name": name,
    "rules": [],          # array of { pattern, template }
    "kind": "declarative", # "declarative" | "procedural"
    "hygiene": "default",  # "default" | "unhygienic"
    "span": nil
  }
}

fn macro_add_rule(def: any, pattern: array, template: array) -> any {
  push(def["rules"], { "pattern": pattern, "template": template })
  return def
}

# ---- Macro Environment ----

fn macro_env_new() -> any {
  return {
    "macros": {},          # name -> MacroDef
    "builtin": {},         # name -> fn
    "call_stack": [],      # for recursion detection
    "max_depth": 64,
    "expansions": 0
  }
}

fn macro_env_define(env: any, name: string, def: any) -> any {
  env["macros"][name] = def
  return env
}

fn macro_env_lookup(env: any, name: string) -> any {
  builtin = env["builtin"][name]
  if builtin != nil { return builtin }
  return env["macros"][name]
}

# ---- Built-in Macros ----

fn macro_register_builtins(env: any) -> any {
  # assert!(expr) — panic if false
  env["builtin"]["assert"] = {
    "name": "assert",
    "kind": "builtin",
    "expand": "builtin_assert"
  }

  # assert_eq!(a, b) — compare with nice error
  env["builtin"]["assert_eq"] = {
    "name": "assert_eq",
    "kind": "builtin",
    "expand": "builtin_assert_eq"
  }

  # assert_ne!(a, b)
  env["builtin"]["assert_ne"] = {
    "name": "assert_ne",
    "kind": "builtin",
    "expand": "builtin_assert_ne"
  }

  # println!(...) — print with newline
  env["builtin"]["println"] = {
    "name": "println",
    "kind": "builtin",
    "expand": "builtin_println"
  }

  # format!(...) — string formatting
  env["builtin"]["format"] = {
    "name": "format",
    "kind": "builtin",
    "expand": "builtin_format"
  }

  # vec![a, b, c] — array literal
  env["builtin"]["vec"] = {
    "name": "vec",
    "kind": "builtin",
    "expand": "builtin_vec"
  }

  # todo!() — not yet implemented marker
  env["builtin"]["todo"] = {
    "name": "todo",
    "kind": "builtin",
    "expand": "builtin_todo"
  }

  # unreachable!() — mark unreachable code
  env["builtin"]["unreachable"] = {
    "name": "unreachable",
    "kind": "builtin",
    "expand": "builtin_unreachable"
  }

  # dbg!(expr) — debug print expression + value
  env["builtin"]["dbg"] = {
    "name": "dbg",
    "kind": "builtin",
    "expand": "builtin_dbg"
  }

  # concat!(a, b, ...) — concat string literals
  env["builtin"]["concat"] = {
    "name": "concat",
    "kind": "builtin",
    "expand": "builtin_concat"
  }

  # include_str!("file") — embed file as string literal
  env["builtin"]["include_str"] = {
    "name": "include_str",
    "kind": "builtin",
    "expand": "builtin_include_str"
  }

  return env
}

# ---- Pattern Matching for Macro Rules ----

fn macro_pattern_new(kind: string) -> any {
  return {
    "kind": kind,
    "name": nil,       # capture variable name
    "children": [],
    "sep": nil,        # repeat separator token
    "quantifier": "*"  # * + ?
  }
}

fn macro_pattern_var(name: string, frag: string) -> any {
  p = macro_pattern_new("var")
  p["name"] = name
  p["frag"] = frag   # expr/stmt/ident/ty etc.
  return p
}

fn macro_pattern_literal(tok: any) -> any {
  p = macro_pattern_new("literal")
  p["token"] = tok
  return p
}

fn macro_pattern_repeat(inner: array, sep: any, quant: string) -> any {
  p = macro_pattern_new("repeat")
  p["children"] = inner
  p["sep"] = sep
  p["quantifier"] = quant
  return p
}

# ---- Macro Matching ----

fn macro_match_rule(rule: any, tokens: array) -> any {
  bindings = {}
  pos = 0
  matched = macro_match_pattern(rule["pattern"], tokens, pos, bindings)
  if matched["ok"] and matched["pos"] == length(tokens) {
    return { "ok": true, "bindings": matched["bindings"] }
  }
  return { "ok": false }
}

fn macro_match_pattern(pattern: array, tokens: array, pos: i32, bindings: any) -> any {
  pi = 0
  cur_pos = pos

  while pi < length(pattern) {
    pat = pattern[pi]
    match pat["kind"] {
      "literal" => {
        if cur_pos >= length(tokens) {
          return { "ok": false, "pos": cur_pos, "bindings": bindings }
        }
        tok = tokens[cur_pos]
        if tok["type"] != pat["token"]["type"] or tok["value"] != pat["token"]["value"] {
          return { "ok": false, "pos": cur_pos, "bindings": bindings }
        }
        cur_pos = cur_pos + 1
      },
      "var" => {
        if cur_pos >= length(tokens) {
          return { "ok": false, "pos": cur_pos, "bindings": bindings }
        }
        result = macro_match_frag(pat["frag"], tokens, cur_pos)
        if not result["ok"] {
          return { "ok": false, "pos": cur_pos, "bindings": bindings }
        }
        bindings[pat["name"]] = result["captured"]
        cur_pos = result["end_pos"]
      },
      "repeat" => {
        captures = []
        inner = pat["children"]
        sep = pat["sep"]
        quant = pat["quantifier"]
        iteration = 0

        while true {
          # Try to match separator first (except first iteration)
          sep_pos = cur_pos
          if iteration > 0 and sep != nil {
            if sep_pos >= length(tokens) { break }
            tok = tokens[sep_pos]
            if tok["type"] != sep["type"] or tok["value"] != sep["value"] { break }
            sep_pos = sep_pos + 1
          }

          # Try to match inner pattern
          inner_bindings = {}
          r = macro_match_pattern(inner, tokens, sep_pos, inner_bindings)
          if not r["ok"] { break }

          push(captures, inner_bindings)
          cur_pos = r["pos"]
          iteration = iteration + 1

          if quant == "?" { break }
        }

        if quant == "+" and length(captures) == 0 {
          return { "ok": false, "pos": cur_pos, "bindings": bindings }
        }
        bindings["_repeat_" + to_string(pi)] = captures
      },
      _ => {}
    }
    pi = pi + 1
  }

  return { "ok": true, "pos": cur_pos, "bindings": bindings }
}

fn macro_match_frag(frag: string, tokens: array, pos: i32) -> any {
  match frag {
    MTOK_IDENT => {
      if pos >= length(tokens) { return { "ok": false } }
      tok = tokens[pos]
      if tok["type"] == "IDENT" {
        return { "ok": true, "captured": tok, "end_pos": pos + 1 }
      }
      return { "ok": false }
    },
    MTOK_LITERAL => {
      if pos >= length(tokens) { return { "ok": false } }
      tok = tokens[pos]
      if tok["type"] == "INT" or tok["type"] == "FLOAT" or tok["type"] == "STRING" or tok["type"] == "BOOL" {
        return { "ok": true, "captured": tok, "end_pos": pos + 1 }
      }
      return { "ok": false }
    },
    MTOK_EXPR => {
      # Consume tokens until delimiter (comma, semicolon, closing bracket)
      captured = []
      i = pos
      depth = 0
      while i < length(tokens) {
        tok = tokens[i]
        t = tok["type"]
        if t == "LPAREN" or t == "LBRACE" or t == "LBRACKET" {
          depth = depth + 1
        } else if t == "RPAREN" or t == "RBRACE" or t == "RBRACKET" {
          if depth == 0 { break }
          depth = depth - 1
        } else if t == "COMMA" and depth == 0 {
          break
        } else if t == "SEMICOLON" and depth == 0 {
          break
        }
        push(captured, tok)
        i = i + 1
      }
      if length(captured) == 0 { return { "ok": false } }
      return { "ok": true, "captured": captured, "end_pos": i }
    },
    MTOK_TT => {
      if pos >= length(tokens) { return { "ok": false } }
      tok = tokens[pos]
      t = tok["type"]
      # Consume a balanced token tree
      if t == "LPAREN" or t == "LBRACE" or t == "LBRACKET" {
        close = if t == "LPAREN" "RPAREN" else if t == "LBRACE" "RBRACE" else "RBRACKET"
        captured = [tok]
        i = pos + 1
        depth = 1
        while i < length(tokens) and depth > 0 {
          tok2 = tokens[i]
          push(captured, tok2)
          if tok2["type"] == t { depth = depth + 1 }
          if tok2["type"] == close { depth = depth - 1 }
          i = i + 1
        }
        return { "ok": true, "captured": captured, "end_pos": i }
      }
      return { "ok": true, "captured": tok, "end_pos": pos + 1 }
    },
    _ => {
      if pos >= length(tokens) { return { "ok": false } }
      return { "ok": true, "captured": tokens[pos], "end_pos": pos + 1 }
    }
  }
}

# ---- Template Expansion ----

fn macro_expand_template(template: array, bindings: any) -> array {
  result = []
  i = 0
  while i < length(template) {
    part = template[i]
    match part["kind"] {
      "var_ref" => {
        # $name
        captured = bindings[part["name"]]
        if captured == nil {
          push(result, part)  # keep as-is
        } else if is_array(captured) {
          j = 0
          while j < length(captured) {
            push(result, captured[j])
            j = j + 1
          }
        } else {
          push(result, captured)
        }
      },
      "repeat_expand" => {
        # $(...)*  expansion
        captures = bindings["_repeat_" + to_string(part["src_index"])]
        if captures != nil {
          k = 0
          while k < length(captures) {
            inner_bindings = captures[k]
            # merge bindings
            merged = dict_merge(bindings, inner_bindings)
            expanded = macro_expand_template(part["children"], merged)
            j = 0
            while j < length(expanded) {
              push(result, expanded[j])
              j = j + 1
            }
            # Add separator if not last
            if k < length(captures) - 1 and part["sep"] != nil {
              push(result, part["sep"])
            }
            k = k + 1
          }
        }
      },
      _ => {
        push(result, part)
      }
    }
    i = i + 1
  }
  return result
}

# ---- Built-in Macro Expansion ----

fn builtin_assert_expand(args: array) -> array {
  # assert!(expr) → if !(expr) { panic!("assertion failed") }
  return [
    tok_kw("if"), tok_op("!"), tok_punct("(")
  ] + args + [
    tok_punct(")"), tok_punct("{"),
    tok_kw("panic"), tok_punct("("),
    tok_str("assertion failed"), tok_punct(")"),
    tok_punct(";"), tok_punct("}")
  ]
}

fn builtin_assert_eq_expand(args: array) -> array {
  # assert_eq!(a, b) → if a != b { panic!("assertion failed: a != b") }
  split = split_args(args)
  a_tokens = if length(split) > 0 split[0] else []
  b_tokens = if length(split) > 1 split[1] else []
  return [tok_kw("if")] + a_tokens +
    [tok_op("!"), tok_op("=")] + b_tokens +
    [tok_punct("{"), tok_kw("panic"), tok_punct("("),
     tok_str("assertion eq failed"), tok_punct(")"),
     tok_punct(";"), tok_punct("}")]
}

fn builtin_println_expand(args: array) -> array {
  # println!(fmt, ...) → print(format!(fmt, ...) + "\n")
  return [tok_ident("print"), tok_punct("(")] + args + [tok_punct("+"), tok_str("\n"), tok_punct(")")]
}

fn builtin_format_expand(args: array) -> array {
  # format!("hello {}", name) → string interpolation call
  return [tok_ident("string_format"), tok_punct("(")] + args + [tok_punct(")")]
}

fn builtin_vec_expand(args: array) -> array {
  # vec![1, 2, 3] → [1, 2, 3]
  return [tok_punct("[")] + args + [tok_punct("]")]
}

fn builtin_todo_expand(args: array) -> array {
  msg = if length(args) > 0 args[0] else tok_str("not yet implemented")
  return [tok_kw("panic"), tok_punct("("), msg, tok_punct(")")]
}

fn builtin_unreachable_expand(args: array) -> array {
  return [tok_kw("panic"), tok_punct("("), tok_str("unreachable code"), tok_punct(")")]
}

fn builtin_dbg_expand(args: array) -> array {
  # dbg!(x) → { print("[dbg] " + to_string(x)); x }
  return [tok_punct("{"),
    tok_ident("print"), tok_punct("("), tok_str("[dbg] "), tok_op("+"),
    tok_ident("to_string"), tok_punct("(")] + args + [tok_punct(")"), tok_punct(")"), tok_punct(";")
  ] + args + [tok_punct("}")]
}

fn builtin_concat_expand(args: array) -> array {
  parts = split_args(args)
  if length(parts) == 0 { return [tok_str("")] }
  result = parts[0]
  i = 1
  while i < length(parts) {
    result = result + [tok_op("+")] + parts[i]
    i = i + 1
  }
  return result
}

# ---- Token Constructors (helpers) ----

fn tok_kw(kw: string) -> any {
  return { "type": "KW", "value": kw }
}

fn tok_ident(name: string) -> any {
  return { "type": "IDENT", "value": name }
}

fn tok_op(op: string) -> any {
  return { "type": "OP", "value": op }
}

fn tok_punct(p: string) -> any {
  return { "type": "PUNCT", "value": p }
}

fn tok_str(s: string) -> any {
  return { "type": "STRING", "value": s }
}

fn tok_int(n: i32) -> any {
  return { "type": "INT", "value": n }
}

fn split_args(tokens: array) -> array {
  # Split tokens by comma at depth 0
  result = []
  current = []
  depth = 0
  i = 0
  while i < length(tokens) {
    tok = tokens[i]
    t = tok["type"]
    if t == "LPAREN" or t == "LBRACE" or t == "LBRACKET" {
      depth = depth + 1
      push(current, tok)
    } else if t == "RPAREN" or t == "RBRACE" or t == "RBRACKET" {
      depth = depth - 1
      push(current, tok)
    } else if t == "COMMA" and depth == 0 {
      push(result, current)
      current = []
    } else {
      push(current, tok)
    }
    i = i + 1
  }
  if length(current) > 0 { push(result, current) }
  return result
}

# ---- Macro Invocation Expansion ----

fn macro_expand_call(env: any, name: string, args: array) -> any {
  # Check recursion depth
  if length(env["call_stack"]) >= env["max_depth"] {
    return { "ok": false, "error": "macro recursion limit exceeded: " + name }
  }

  def = macro_env_lookup(env, name)
  if def == nil {
    return { "ok": false, "error": "undefined macro: " + name }
  }

  push(env["call_stack"], name)
  env["expansions"] = env["expansions"] + 1

  result = nil
  match def["kind"] {
    "builtin" => {
      handler = def["expand"]
      match handler {
        "builtin_assert"       => { result = builtin_assert_expand(args) },
        "builtin_assert_eq"    => { result = builtin_assert_eq_expand(args) },
        "builtin_assert_ne"    => { result = builtin_assert_eq_expand(args) },  # similar
        "builtin_println"      => { result = builtin_println_expand(args) },
        "builtin_format"       => { result = builtin_format_expand(args) },
        "builtin_vec"          => { result = builtin_vec_expand(args) },
        "builtin_todo"         => { result = builtin_todo_expand(args) },
        "builtin_unreachable"  => { result = builtin_unreachable_expand(args) },
        "builtin_dbg"          => { result = builtin_dbg_expand(args) },
        "builtin_concat"       => { result = builtin_concat_expand(args) },
        "builtin_include_str"  => { result = [tok_str("[embedded file]")] },
        _ => { result = args }
      }
    },
    "declarative" => {
      # Try each rule in order
      i = 0
      while i < length(def["rules"]) {
        rule = def["rules"][i]
        m = macro_match_rule(rule, args)
        if m["ok"] {
          result = macro_expand_template(rule["template"], m["bindings"])
          break
        }
        i = i + 1
      }
      if result == nil {
        pop(env["call_stack"])
        return { "ok": false, "error": "no matching macro rule for: " + name }
      }
    },
    "procedural" => {
      # Procedural macros: treat def["transform"] as function name
      transform = def["transform"]
      result = proc_macro_apply(transform, args, env)
    },
    _ => {
      result = args
    }
  }

  pop(env["call_stack"])
  return { "ok": true, "tokens": result }
}

# ---- Procedural Macros ----

fn proc_macro_apply(transform: string, args: array, env: any) -> array {
  # Procedural macros transform token streams
  # Common ones:
  match transform {
    "derive_debug" => {
      # #[derive(Debug)] - generate debug fmt implementation
      return proc_derive_debug(args)
    },
    "derive_clone" => {
      return proc_derive_clone(args)
    },
    "derive_eq" => {
      return proc_derive_eq(args)
    },
    "derive_hash" => {
      return proc_derive_hash(args)
    },
    _ => {
      return args
    }
  }
}

fn proc_derive_debug(struct_tokens: array) -> array {
  # Extract struct name from tokens and generate fmt_debug fn
  name = extract_struct_name(struct_tokens)
  return [
    tok_kw("fn"), tok_ident("fmt_debug"), tok_punct("("),
    tok_ident("self"), tok_punct(":"), tok_ident("Self"),
    tok_punct(")"), tok_op("->"), tok_ident("string"),
    tok_punct("{"),
    tok_ident("to_string"), tok_punct("("), tok_ident("self"), tok_punct(")"),
    tok_punct("}")
  ]
}

fn proc_derive_clone(struct_tokens: array) -> array {
  name = extract_struct_name(struct_tokens)
  return [
    tok_kw("fn"), tok_ident("clone"), tok_punct("("),
    tok_ident("self"), tok_punct(":"), tok_ident("Self"),
    tok_punct(")"), tok_op("->"), tok_ident("Self"),
    tok_punct("{"), tok_ident("self"), tok_punct("}")
  ]
}

fn proc_derive_eq(struct_tokens: array) -> array {
  name = extract_struct_name(struct_tokens)
  return [
    tok_kw("fn"), tok_ident("eq"), tok_punct("("),
    tok_ident("self"), tok_punct(":"), tok_ident("Self"), tok_punct(","),
    tok_ident("other"), tok_punct(":"), tok_ident("Self"),
    tok_punct(")"), tok_op("->"), tok_ident("bool"),
    tok_punct("{"), tok_ident("self"), tok_op("=="), tok_ident("other"), tok_punct("}")
  ]
}

fn proc_derive_hash(struct_tokens: array) -> array {
  return [
    tok_kw("fn"), tok_ident("hash"), tok_punct("("),
    tok_ident("self"), tok_punct(":"), tok_ident("Self"),
    tok_punct(")"), tok_op("->"), tok_ident("u64"),
    tok_punct("{"), tok_int(0), tok_punct("}")  # placeholder
  ]
}

fn extract_struct_name(tokens: array) -> string {
  i = 0
  while i < length(tokens) {
    tok = tokens[i]
    if (tok["type"] == "KW" and tok["value"] == "struct") or
       (tok["type"] == "KW" and tok["value"] == "enum") {
      if i + 1 < length(tokens) {
        return tokens[i + 1]["value"]
      }
    }
    i = i + 1
  }
  return "Unknown"
}

# ---- Macro Expansion Pass (full AST walk) ----

fn macro_expand_ast(ast: any, env: any) -> any {
  match ast["kind"] {
    "macro_call" => {
      name = ast["name"]
      args = ast["args"]
      r = macro_expand_call(env, name, args)
      if r["ok"] {
        # Re-parse expanded tokens back to AST
        return { "kind": "expanded_macro", "tokens": r["tokens"], "original": ast }
      }
      return { "kind": "error_node", "error": r["error"] }
    },
    "block" => {
      stmts = []
      i = 0
      while i < length(ast["stmts"]) {
        expanded = macro_expand_ast(ast["stmts"][i], env)
        push(stmts, expanded)
        i = i + 1
      }
      ast["stmts"] = stmts
      return ast
    },
    "fn_def" => {
      ast["body"] = macro_expand_ast(ast["body"], env)
      return ast
    },
    "if_stmt" => {
      ast["then_block"] = macro_expand_ast(ast["then_block"], env)
      if ast["else_block"] != nil {
        ast["else_block"] = macro_expand_ast(ast["else_block"], env)
      }
      return ast
    },
    "while_stmt" => {
      ast["body"] = macro_expand_ast(ast["body"], env)
      return ast
    },
    _ => {
      return ast
    }
  }
}

# ---- macro_rules! Parser ----
# Parses: macro_rules! name { (pattern) => { template }, ... }

fn parse_macro_rules(tokens: array, pos: i32) -> any {
  # Expect: macro_rules ! name { rules... }
  cur = pos
  if cur >= length(tokens) { return { "ok": false } }

  # skip "macro_rules"
  if tokens[cur]["value"] != "macro_rules" { return { "ok": false } }
  cur = cur + 1
  # skip "!"
  cur = cur + 1
  # macro name
  name = tokens[cur]["value"]
  cur = cur + 1
  # skip "{"
  cur = cur + 1

  def = macro_def_new(name)

  while cur < length(tokens) and tokens[cur]["value"] != "}" {
    # (pattern) => { template }
    if tokens[cur]["type"] != "LPAREN" { break }
    cur = cur + 1

    # Parse pattern until ")"
    pattern = []
    while cur < length(tokens) and tokens[cur]["type"] != "RPAREN" {
      tok = tokens[cur]
      if tok["value"] == "$" {
        cur = cur + 1
        frag_name = tokens[cur]["value"]
        cur = cur + 1
        # skip ":"
        cur = cur + 1
        frag_kind = tokens[cur]["value"]
        cur = cur + 1
        push(pattern, macro_pattern_var(frag_name, frag_kind))
      } else {
        push(pattern, macro_pattern_literal(tok))
        cur = cur + 1
      }
    }
    cur = cur + 1  # skip ")"

    # skip "=>"
    cur = cur + 2

    # skip "{"
    cur = cur + 1

    # Parse template until "}"
    template = []
    depth = 1
    while cur < length(tokens) {
      tok = tokens[cur]
      if tok["type"] == "LBRACE" { depth = depth + 1 }
      if tok["type"] == "RBRACE" {
        depth = depth - 1
        if depth == 0 { cur = cur + 1; break }
      }
      if tok["value"] == "$" and cur + 1 < length(tokens) {
        cur = cur + 1
        ref_name = tokens[cur]["value"]
        push(template, { "kind": "var_ref", "name": ref_name })
      } else {
        push(template, tok)
      }
      cur = cur + 1
    }

    macro_add_rule(def, pattern, template)

    # skip optional ","
    if cur < length(tokens) and tokens[cur]["type"] == "COMMA" { cur = cur + 1 }
  }

  cur = cur + 1  # skip "}"

  return { "ok": true, "def": def, "end_pos": cur }
}

# ---- Statistics ----

fn macro_env_stats(env: any) -> any {
  return {
    "macros_defined": dict_len(env["macros"]),
    "builtins": dict_len(env["builtin"]),
    "total_expansions": env["expansions"],
    "call_stack_depth": length(env["call_stack"])
  }
}

fn macro_env_report(env: any) -> string {
  stats = macro_env_stats(env)
  out = "=== Macro System ===\n"
  out = out + "Defined macros:  " + to_string(stats["macros_defined"]) + "\n"
  out = out + "Built-in macros: " + to_string(stats["builtins"]) + "\n"
  out = out + "Total expansions:" + to_string(stats["total_expansions"]) + "\n"
  return out
}

