# ================================================================
# FreeLang v4 Core - Async/Await Runtime
# Single-threaded cooperative task scheduler
# Supports: async fn, await, Future<T>, select!, join!
# ================================================================

# ---- Poll Result ----

POLL_READY   = "ready"
POLL_PENDING = "pending"

fn poll_ready(value: any) -> any {
  return { "state": POLL_READY, "value": value }
}

fn poll_pending() -> any {
  return { "state": POLL_PENDING, "value": nil }
}

fn poll_is_ready(p: any) -> bool {
  return p["state"] == POLL_READY
}

# ---- Future ----

fn future_new(poll_fn: string, state: any) -> any {
  return {
    "id": 0,
    "poll_fn": poll_fn,     # function name to call with (future, cx)
    "state": state,
    "completed": false,
    "result": nil,
    "waker": nil
  }
}

fn future_ready(value: any) -> any {
  f = future_new("future_poll_ready", nil)
  f["completed"] = true
  f["result"] = value
  return f
}

fn future_pending_fn() -> any {
  return future_new("future_poll_never", nil)
}

fn future_poll_ready(future: any, cx: any) -> any {
  return poll_ready(future["result"])
}

fn future_poll_never(future: any, cx: any) -> any {
  return poll_pending()
}

# ---- Waker ----

fn waker_new(task_id: i32, reactor: any) -> any {
  return { "task_id": task_id, "reactor": reactor }
}

fn waker_wake(waker: any) -> any {
  if waker == nil { return nil }
  reactor = waker["reactor"]
  if reactor != nil {
    async_reactor_wake(reactor, waker["task_id"])
  }
  return nil
}

# ---- Context (passed to poll) ----

fn context_new(waker: any) -> any {
  return { "waker": waker }
}

# ---- Task ----

TASK_PENDING   = "pending"
TASK_READY     = "ready"
TASK_RUNNING   = "running"
TASK_COMPLETED = "completed"
TASK_FAILED    = "failed"

fn task_new(id: i32, future: any) -> any {
  return {
    "id": id,
    "future": future,
    "state": TASK_READY,
    "result": nil,
    "error": nil,
    "name": "task_" + to_string(id),
    "priority": 0,
    "created_at": time_now(),
    "started_at": 0,
    "completed_at": 0,
    "poll_count": 0
  }
}

# ---- Reactor ----

fn async_reactor_new() -> any {
  return {
    "ready_queue": [],    # task IDs that are ready to run
    "sleeping": {},       # task_id -> wake_condition
    "io_watchers": [],    # { fd, event, task_id }
    "timers": []          # { deadline, task_id }
  }
}

fn async_reactor_wake(reactor: any, task_id: i32) -> any {
  push(reactor["ready_queue"], task_id)
  dict_delete(reactor["sleeping"], to_string(task_id))
  return reactor
}

fn async_reactor_sleep(reactor: any, task_id: i32) -> any {
  reactor["sleeping"][to_string(task_id)] = true
  return reactor
}

fn async_reactor_register_timer(reactor: any, task_id: i32, delay_ms: i32) -> any {
  deadline = time_now() + delay_ms
  push(reactor["timers"], { "deadline": deadline, "task_id": task_id })
  return reactor
}

fn async_reactor_poll_timers(reactor: any) -> any {
  now = time_now()
  i = 0
  while i < length(reactor["timers"]) {
    timer = reactor["timers"][i]
    if now >= timer["deadline"] {
      async_reactor_wake(reactor, timer["task_id"])
      # Remove expired timer
      arr_remove_at(reactor["timers"], i)
    } else {
      i = i + 1
    }
  }
  return reactor
}

# ---- Executor ----

fn executor_new() -> any {
  return {
    "tasks": {},          # task_id -> Task
    "next_id": 1,
    "reactor": async_reactor_new(),
    "running": false,
    "stats": {
      "spawned": 0,
      "completed": 0,
      "failed": 0,
      "total_polls": 0
    }
  }
}

fn executor_spawn(ex: any, future: any) -> i32 {
  id = ex["next_id"]
  ex["next_id"] = ex["next_id"] + 1
  task = task_new(id, future)
  ex["tasks"][to_string(id)] = task
  async_reactor_wake(ex["reactor"], id)
  ex["stats"]["spawned"] = ex["stats"]["spawned"] + 1
  return id
}

fn executor_spawn_named(ex: any, future: any, name: string) -> i32 {
  id = executor_spawn(ex, future)
  ex["tasks"][to_string(id)]["name"] = name
  return id
}

fn executor_run(ex: any) -> any {
  # Run until all tasks complete
  ex["running"] = true
  while executor_has_work(ex) {
    executor_tick(ex)
  }
  ex["running"] = false
  return ex
}

fn executor_run_until(ex: any, task_id: i32) -> any {
  # Run until specific task completes
  while true {
    task = ex["tasks"][to_string(task_id)]
    if task == nil or task["state"] == TASK_COMPLETED or task["state"] == TASK_FAILED {
      break
    }
    executor_tick(ex)
  }
  task = ex["tasks"][to_string(task_id)]
  if task == nil { return nil }
  return task["result"]
}

fn executor_has_work(ex: any) -> bool {
  if length(ex["reactor"]["ready_queue"]) > 0 { return true }
  if length(ex["reactor"]["timers"]) > 0 { return true }
  # Check if any pending tasks
  keys = dict_keys(ex["tasks"])
  i = 0
  while i < length(keys) {
    task = ex["tasks"][keys[i]]
    if task["state"] != TASK_COMPLETED and task["state"] != TASK_FAILED {
      return true
    }
    i = i + 1
  }
  return false
}

fn executor_tick(ex: any) -> any {
  # Poll expired timers
  ex["reactor"] = async_reactor_poll_timers(ex["reactor"])

  # Process ready queue
  if length(ex["reactor"]["ready_queue"]) == 0 {
    # Nothing ready - yield
    return ex
  }

  task_id = ex["reactor"]["ready_queue"][0]
  arr_remove_at(ex["reactor"]["ready_queue"], 0)

  task = ex["tasks"][to_string(task_id)]
  if task == nil or task["state"] == TASK_COMPLETED or task["state"] == TASK_FAILED {
    return ex
  }

  # Poll the future
  task["state"] = TASK_RUNNING
  task["poll_count"] = task["poll_count"] + 1
  if task["started_at"] == 0 { task["started_at"] = time_now() }

  waker = waker_new(task_id, ex["reactor"])
  cx = context_new(waker)

  result = future_do_poll(task["future"], cx)
  ex["stats"]["total_polls"] = ex["stats"]["total_polls"] + 1

  if poll_is_ready(result) {
    task["state"] = TASK_COMPLETED
    task["result"] = result["value"]
    task["completed_at"] = time_now()
    ex["stats"]["completed"] = ex["stats"]["completed"] + 1
  } else {
    # Still pending - reactor will re-queue when woken
    task["state"] = TASK_PENDING
    async_reactor_sleep(ex["reactor"], task_id)
  }

  ex["tasks"][to_string(task_id)] = task
  return ex
}

fn future_do_poll(future: any, cx: any) -> any {
  if future["completed"] {
    return poll_ready(future["result"])
  }
  poll_fn = future["poll_fn"]
  match poll_fn {
    "future_poll_ready" => { return future_poll_ready(future, cx) },
    "future_poll_never" => { return future_poll_never(future, cx) },
    "sleep_future_poll" => { return sleep_future_poll(future, cx) },
    "channel_recv_poll" => { return channel_recv_poll(future, cx) },
    "join_future_poll"  => { return join_future_poll(future, cx) },
    "select_future_poll" => { return select_future_poll(future, cx) },
    _ => { return poll_pending() }
  }
}

# ---- Sleep Future ----

fn sleep_future_new(ms: i32) -> any {
  f = future_new("sleep_future_poll", {
    "deadline": time_now() + ms,
    "registered": false
  })
  return f
}

fn sleep_future_poll(future: any, cx: any) -> any {
  now = time_now()
  if now >= future["state"]["deadline"] {
    future["completed"] = true
    return poll_ready(nil)
  }
  # Register timer with reactor
  if not future["state"]["registered"] {
    waker = cx["waker"]
    if waker != nil {
      async_reactor_register_timer(
        waker["reactor"],
        waker["task_id"],
        future["state"]["deadline"] - now
      )
      future["state"]["registered"] = true
    }
  }
  return poll_pending()
}

# ---- Channels ----

CHAN_UNBOUNDED = -1

fn channel_new(capacity: i32) -> any {
  return {
    "id": 0,
    "buf": [],
    "capacity": capacity,
    "closed": false,
    "senders": 0,
    "receivers": 0,
    "waiting_recv": [],   # task_ids waiting to receive
    "waiting_send": []    # { task_id, value } waiting to send
  }
}

fn channel_pair(capacity: i32) -> any {
  ch = channel_new(capacity)
  sender = { "channel": ch, "kind": "sender" }
  receiver = { "channel": ch, "kind": "receiver" }
  return { "sender": sender, "receiver": receiver }
}

fn channel_send(sender: any, value: any, reactor: any) -> bool {
  ch = sender["channel"]
  if ch["closed"] { return false }

  capacity = ch["capacity"]
  if capacity == CHAN_UNBOUNDED or length(ch["buf"]) < capacity {
    push(ch["buf"], value)
    # Wake up waiting receivers
    if length(ch["waiting_recv"]) > 0 {
      recv_id = ch["waiting_recv"][0]
      arr_remove_at(ch["waiting_recv"], 0)
      async_reactor_wake(reactor, recv_id)
    }
    return true
  }
  return false  # channel full
}

fn channel_try_recv(receiver: any) -> any {
  ch = receiver["channel"]
  if length(ch["buf"]) > 0 {
    val = ch["buf"][0]
    arr_remove_at(ch["buf"], 0)
    return { "ok": true, "value": val }
  }
  if ch["closed"] { return { "ok": false, "closed": true } }
  return { "ok": false, "closed": false }
}

fn channel_recv_future(receiver: any) -> any {
  return future_new("channel_recv_poll", {
    "receiver": receiver,
    "registered": false
  })
}

fn channel_recv_poll(future: any, cx: any) -> any {
  receiver = future["state"]["receiver"]
  result = channel_try_recv(receiver)
  if result["ok"] {
    future["completed"] = true
    return poll_ready(result["value"])
  }
  if result["closed"] {
    future["completed"] = true
    return poll_ready(nil)
  }
  # Register self in waiting list
  if not future["state"]["registered"] {
    waker = cx["waker"]
    if waker != nil {
      push(receiver["channel"]["waiting_recv"], waker["task_id"])
      future["state"]["registered"] = true
    }
  }
  return poll_pending()
}

fn channel_close(channel: any, reactor: any) -> any {
  channel["closed"] = true
  # Wake all waiting receivers
  i = 0
  while i < length(channel["waiting_recv"]) {
    async_reactor_wake(reactor, channel["waiting_recv"][i])
    i = i + 1
  }
  channel["waiting_recv"] = []
  return channel
}

# ---- Join (wait for all futures) ----

fn join_future_new(futures: array) -> any {
  results = []
  i = 0
  while i < length(futures) {
    push(results, nil)
    i = i + 1
  }
  return future_new("join_future_poll", {
    "futures": futures,
    "results": results,
    "done_count": 0
  })
}

fn join_future_poll(future: any, cx: any) -> any {
  state = future["state"]
  all_done = true
  i = 0
  while i < length(state["futures"]) {
    if state["results"][i] == nil {
      r = future_do_poll(state["futures"][i], cx)
      if poll_is_ready(r) {
        state["results"][i] = r["value"]
        state["done_count"] = state["done_count"] + 1
      } else {
        all_done = false
      }
    }
    i = i + 1
  }
  if all_done or state["done_count"] == length(state["futures"]) {
    future["completed"] = true
    return poll_ready(state["results"])
  }
  return poll_pending()
}

# ---- Select (first to complete wins) ----

fn select_future_new(futures: array) -> any {
  return future_new("select_future_poll", {
    "futures": futures,
    "winner_idx": -1
  })
}

fn select_future_poll(future: any, cx: any) -> any {
  state = future["state"]
  i = 0
  while i < length(state["futures"]) {
    r = future_do_poll(state["futures"][i], cx)
    if poll_is_ready(r) {
      future["completed"] = true
      state["winner_idx"] = i
      return poll_ready({ "index": i, "value": r["value"] })
    }
    i = i + 1
  }
  return poll_pending()
}

# ---- Async/Await DSL Helpers ----

# async_fn wraps a synchronous function result in a future
fn async_fn(value: any) -> any {
  return future_ready(value)
}

# await blocks on a future (in executor context)
fn async_await(ex: any, future: any) -> any {
  id = executor_spawn(ex, future)
  result = executor_run_until(ex, id)
  return result
}

# async_sleep — yield for N milliseconds
fn async_sleep(ms: i32) -> any {
  return sleep_future_new(ms)
}

# ---- Task Utilities ----

fn task_get_result(ex: any, task_id: i32) -> any {
  task = ex["tasks"][to_string(task_id)]
  if task == nil { return nil }
  if task["state"] == TASK_COMPLETED { return task["result"] }
  return nil
}

fn task_is_done(ex: any, task_id: i32) -> bool {
  task = ex["tasks"][to_string(task_id)]
  if task == nil { return true }
  return task["state"] == TASK_COMPLETED or task["state"] == TASK_FAILED
}

# ---- Executor Statistics ----

fn executor_stats(ex: any) -> any {
  completed = 0
  pending = 0
  failed = 0
  total_polls = 0

  keys = dict_keys(ex["tasks"])
  i = 0
  while i < length(keys) {
    task = ex["tasks"][keys[i]]
    if task["state"] == TASK_COMPLETED { completed = completed + 1 }
    else if task["state"] == TASK_FAILED { failed = failed + 1 }
    else { pending = pending + 1 }
    total_polls = total_polls + task["poll_count"]
    i = i + 1
  }

  return {
    "total_tasks": length(keys),
    "completed": completed,
    "pending": pending,
    "failed": failed,
    "total_polls": total_polls,
    "reactor_ready": length(ex["reactor"]["ready_queue"]),
    "reactor_timers": length(ex["reactor"]["timers"])
  }
}

fn executor_report(ex: any) -> string {
  s = executor_stats(ex)
  out = "=== Async Executor Report ===\n"
  out = out + "Tasks:     " + to_string(s["total_tasks"]) + "\n"
  out = out + "Completed: " + to_string(s["completed"]) + "\n"
  out = out + "Pending:   " + to_string(s["pending"]) + "\n"
  out = out + "Failed:    " + to_string(s["failed"]) + "\n"
  out = out + "Polls:     " + to_string(s["total_polls"]) + "\n"
  out = out + "Ready Q:   " + to_string(s["reactor_ready"]) + "\n"
  out = out + "Timers:    " + to_string(s["reactor_timers"]) + "\n"
  return out
}

