# ================================================================
# FreeLang v4 Core - Async/Await Runtime
# Single-threaded cooperative task scheduler
# Supports: async fn, await, Future<T>, select!, join!
# ================================================================

# ---- Poll Result ----

POLL_READY   = "ready"
POLL_PENDING = "pending"

fn poll_ready(value: any) -> any {
  return { "state": POLL_READY, "value": value }
}

fn poll_pending() -> any {
  return { "state": POLL_PENDING, "value": nil }
}

fn poll_is_ready(p: any) -> bool {
  return p["state"] == POLL_READY
}

# ---- Future ----

fn future_new(poll_fn: string, state: any) -> any {
  return {
    "id": 0,
    "poll_fn": poll_fn,     # function name to call with (future, cx)
    "state": state,
    "completed": false,
    "result": nil,
    "waker": nil
  }
}

fn future_ready(value: any) -> any {
  f = future_new("future_poll_ready", nil)
  f["completed"] = true
  f["result"] = value
  return f
}

fn future_pending_fn() -> any {
  return future_new("future_poll_never", nil)
}

fn future_poll_ready(future: any, cx: any) -> any {
  return poll_ready(future["result"])
}

fn future_poll_never(future: any, cx: any) -> any {
  return poll_pending()
}

# ---- Waker ----

fn waker_new(task_id: i32, reactor: any) -> any {
  return { "task_id": task_id, "reactor": reactor }
}

fn waker_wake(waker: any) -> any {
  if waker == nil { return nil }
  reactor = waker["reactor"]
  if reactor != nil {
    async_reactor_wake(reactor, waker["task_id"])
  }
  return nil
}

# ---- Context (passed to poll) ----

fn context_new(waker: any) -> any {
  return { "waker": waker }
}

# ---- Task ----

TASK_PENDING   = "pending"
TASK_READY     = "ready"
TASK_RUNNING   = "running"
TASK_COMPLETED = "completed"
TASK_FAILED    = "failed"

fn task_new(id: i32, future: any) -> any {
  return {
    "id": id,
    "future": future,
    "state": TASK_READY,
    "result": nil,
    "error": nil,
    "name": "task_" + to_string(id),
    "priority": 0,
    "created_at": time_now(),
    "started_at": 0,
    "completed_at": 0,
    "poll_count": 0
  }
}

# ---- Reactor ----

fn async_reactor_new() -> any {
  return {
    "ready_queue": [],    # task IDs that are ready to run
    "sleeping": {},       # task_id -> wake_condition
    "io_watchers": [],    # { fd, event, task_id }
    "timers": []          # { deadline, task_id }
  }
}

fn async_reactor_wake(reactor: any, task_id: i32) -> any {
  push(reactor["ready_queue"], task_id)
  dict_delete(reactor["sleeping"], to_string(task_id))
  return reactor
}

fn async_reactor_sleep(reactor: any, task_id: i32) -> any {
  reactor["sleeping"][to_string(task_id)] = true
  return reactor
}

fn async_reactor_register_timer(reactor: any, task_id: i32, delay_ms: i32) -> any {
  deadline = time_now() + delay_ms
  push(reactor["timers"], { "deadline": deadline, "task_id": task_id })
  return reactor
}

fn async_reactor_poll_timers(reactor: any) -> any {
  now = time_now()
  i = 0
  while i < length(reactor["timers"]) {
    timer = reactor["timers"][i]
    if now >= timer["deadline"] {
      async_reactor_wake(reactor, timer["task_id"])
      # Remove expired timer
      arr_remove_at(reactor["timers"], i)
    } else {
      i = i + 1
    }
  }
  return reactor
}

# ---- Executor ----

fn executor_new() -> any {
  return {
    "tasks": {},          # task_id -> Task
    "next_id": 1,
    "reactor": async_reactor_new(),
    "running": false,
    "stats": {
      "spawned": 0,
      "completed": 0,
      "failed": 0,
      "total_polls": 0
    }
  }
}

fn executor_spawn(ex: any, future: any) -> i32 {
  id = ex["next_id"]
  ex["next_id"] = ex["next_id"] + 1
  task = task_new(id, future)
  ex["tasks"][to_string(id)] = task
  async_reactor_wake(ex["reactor"], id)
  ex["stats"]["spawned"] = ex["stats"]["spawned"] + 1
  return id
}

fn executor_spawn_named(ex: any, future: any, name: string) -> i32 {
  id = executor_spawn(ex, future)
  ex["tasks"][to_string(id)]["name"] = name
  return id
}

fn executor_run(ex: any) -> any {
  # Run until all tasks complete
  ex["running"] = true
  while executor_has_work(ex) {
    executor_tick(ex)
  }
  ex["running"] = false
  return ex
}

fn executor_run_until(ex: any, task_id: i32) -> any {
  # Run until specific task completes
  while true {
    task = ex["tasks"][to_string(task_id)]
    if task == nil or task["state"] == TASK_COMPLETED or task["state"] == TASK_FAILED {
      break
    }
    executor_tick(ex)
  }
  task = ex["tasks"][to_string(task_id)]
  if task == nil { return nil }
  return task["result"]
}

fn executor_has_work(ex: any) -> bool {
  if length(ex["reactor"]["ready_queue"]) > 0 { return true }
  if length(ex["reactor"]["timers"]) > 0 { return true }
  # Check if any pending tasks
  keys = dict_keys(ex["tasks"])
  i = 0
  while i < length(keys) {
    task = ex["tasks"][keys[i]]
    if task["state"] != TASK_COMPLETED and task["state"] != TASK_FAILED {
      return true
    }
    i = i + 1
  }
  return false
