    task["completed_at"] = time_now()
    ex["stats"]["completed"] = ex["stats"]["completed"] + 1
  } else {
    # Still pending - reactor will re-queue when woken
    task["state"] = TASK_PENDING
    async_reactor_sleep(ex["reactor"], task_id)
  }

  ex["tasks"][to_string(task_id)] = task
  return ex
}

