    "completed": completed,
    "pending": pending,
    "failed": failed,
    "total_polls": total_polls,
    "reactor_ready": length(ex["reactor"]["ready_queue"]),
    "reactor_timers": length(ex["reactor"]["timers"])
  }
}

fn executor_report(ex: any) -> string {
