# ================================================================
# FreeLang v4 Core - Network Standard Library
# TCP/UDP sockets, DNS, TLS abstraction
# Backed by shell commands (curl/nc/socat) for portability
# ================================================================

# ---- Address / Endpoint ----

fn net_addr(host: string, port: i32) -> any {
  return { "host": host, "port": port, "resolved": nil }
}

fn net_addr_loopback(port: i32) -> any {
  return net_addr("127.0.0.1", port)
}

fn net_addr_any(port: i32) -> any {
  return net_addr("0.0.0.0", port)
}

fn net_addr_str(addr: any) -> string {
  return addr["host"] + ":" + to_string(addr["port"])
}

# ---- DNS ----

fn dns_lookup(hostname: string) -> any {
  # Use system getent or nslookup
  result = shell_exec("getent hosts " + shell_escape(hostname) + " 2>/dev/null | awk '{print $1}' | head -1")
  ip = str_trim(result["stdout"])
  if ip == "" {
    return { "ok": false, "error": "dns lookup failed: " + hostname }
  }
  return { "ok": true, "ip": ip, "hostname": hostname }
}

fn dns_lookup_all(hostname: string) -> any {
  result = shell_exec("getent hosts " + shell_escape(hostname) + " 2>/dev/null | awk '{print $1}'")
  lines = str_split_lines(str_trim(result["stdout"]))
  ips = []
  i = 0
  while i < length(lines) {
    line = str_trim(lines[i])
    if line != "" { push(ips, line) }
    i = i + 1
  }
  return { "ok": length(ips) > 0, "ips": ips }
}

fn dns_reverse(ip: string) -> any {
  result = shell_exec("getent hosts " + shell_escape(ip) + " 2>/dev/null | awk '{print $2}' | head -1")
  hostname = str_trim(result["stdout"])
  if hostname == "" {
    return { "ok": false, "error": "reverse dns failed: " + ip }
  }
  return { "ok": true, "hostname": hostname }
}

# ---- TCP Client ----

fn tcp_connect(host: string, port: i32, timeout_sec: i32) -> any {
  addr = net_addr(host, port)
  t = to_string(timeout_sec)
  # Test connectivity with nc
  result = shell_exec("nc -z -w " + t + " " + shell_escape(host) + " " + to_string(port) + " 2>&1; echo $?")
  exit_code = str_trim(result["stdout"])
  if exit_code != "0" {
    return { "ok": false, "error": "connection refused: " + net_addr_str(addr) }
  }
  return {
    "ok": true,
    "addr": addr,
    "state": "connected",
    "local_port": 0    # not available without raw sockets
  }
}

fn tcp_send(conn: any, data: string) -> any {
  if not conn["ok"] { return { "ok": false, "error": "not connected" } }
  # Write via nc with heredoc
  escaped = shell_escape(data)
  result = shell_exec("echo " + escaped + " | nc -q 1 " +
    shell_escape(conn["addr"]["host"]) + " " + to_string(conn["addr"]["port"]) + " 2>&1")
  return { "ok": result["exit_code"] == 0, "bytes_sent": str_len(data) }
}

fn tcp_recv_line(conn: any, timeout_sec: i32) -> any {
  if not conn["ok"] { return { "ok": false, "error": "not connected" } }
  result = shell_exec("timeout " + to_string(timeout_sec) +
    " nc -q " + to_string(timeout_sec) + " " +
    shell_escape(conn["addr"]["host"]) + " " + to_string(conn["addr"]["port"]) + " 2>&1")
  return { "ok": result["exit_code"] == 0, "data": result["stdout"] }
}

fn tcp_close(conn: any) -> any {
  conn["state"] = "closed"
  return conn
}

# ---- TCP Server ----

fn tcp_server_new(addr: any) -> any {
  return {
    "addr": addr,
    "state": "stopped",
    "pid": 0,
    "connections": 0,
    "backlog": 128
  }
}

fn tcp_server_start(server: any) -> any {
  # Start netcat listener (for simple servers)
  result = shell_exec("nc -l " + shell_escape(server["addr"]["host"]) + " " +
    to_string(server["addr"]["port"]) + " &; echo $!")
  pid = str_to_int(str_trim(result["stdout"]))
  server["pid"] = pid
  server["state"] = "running"
  return { "ok": true, "server": server }
}

fn tcp_server_stop(server: any) -> any {
  if server["pid"] > 0 {
    shell_exec("kill " + to_string(server["pid"]) + " 2>/dev/null")
    server["pid"] = 0
  }
  server["state"] = "stopped"
  return server
}

fn tcp_server_accept(server: any, timeout_sec: i32) -> any {
  # Use socat for more capable server
  result = shell_exec("timeout " + to_string(timeout_sec) +
    " socat - TCP-LISTEN:" + to_string(server["addr"]["port"]) + ",reuseaddr 2>&1")
  if result["exit_code"] != 0 {
    return { "ok": false, "error": "accept timeout or error" }
  }
  server["connections"] = server["connections"] + 1
  return { "ok": true, "data": result["stdout"] }
}

# ---- UDP ----

fn udp_socket_new() -> any {
  return { "state": "open", "local_port": 0 }
}

fn udp_send(sock: any, host: string, port: i32, data: string) -> any {
  result = shell_exec("echo " + shell_escape(data) + " | socat - UDP:" +
    shell_escape(host) + ":" + to_string(port) + " 2>&1")
  return { "ok": result["exit_code"] == 0, "bytes": str_len(data) }
}

fn udp_recv(sock: any, local_port: i32, timeout_sec: i32) -> any {
  result = shell_exec("timeout " + to_string(timeout_sec) +
    " socat - UDP-LISTEN:" + to_string(local_port) + " 2>&1")
  if result["exit_code"] != 0 {
    return { "ok": false, "error": "udp recv timeout" }
  }
  return { "ok": true, "data": result["stdout"] }
}

# ---- TLS/SSL ----

fn tls_connect(host: string, port: i32, verify: bool) -> any {
  verify_flag = if verify "" else "--insecure"
  result = shell_exec("openssl s_client -connect " + shell_escape(host) + ":" +
    to_string(port) + " -brief 2>&1 </dev/null")
  if result["exit_code"] != 0 and not str_contains(result["stderr"], "Verify return code: 0") {
    return { "ok": false, "error": "tls handshake failed" }
  }
  return {
    "ok": true,
    "host": host,
    "port": port,
    "protocol": parse_tls_protocol(result["stdout"]),
    "cipher": parse_tls_cipher(result["stdout"])
  }
}

fn tls_get_cert(host: string, port: i32) -> any {
  result = shell_exec("echo | openssl s_client -connect " + shell_escape(host) + ":" +
    to_string(port) + " -showcerts 2>/dev/null | openssl x509 -noout -text 2>/dev/null | head -30")
  return { "ok": result["exit_code"] == 0, "info": result["stdout"] }
}

fn parse_tls_protocol(output: string) -> string {
  if str_contains(output, "TLSv1.3") { return "TLSv1.3" }
  if str_contains(output, "TLSv1.2") { return "TLSv1.2" }
  if str_contains(output, "TLSv1.1") { return "TLSv1.1" }
  return "unknown"
}

fn parse_tls_cipher(output: string) -> string {
  lines = str_split_lines(output)
  i = 0
  while i < length(lines) {
    line = lines[i]
    if str_contains(line, "Cipher") {
      parts = str_split(line, ":")
      if length(parts) > 1 { return str_trim(parts[1]) }
    }
    i = i + 1
  }
  return "unknown"
}

# ---- HTTP Client (high-level) ----

fn http_get(url: string) -> any {
  result = shell_exec("curl -s -S -L --max-time 30 -w '\\n%{http_code}' " + shell_escape(url) + " 2>&1")
  return parse_curl_response(result)
}

fn http_get_headers(url: string) -> any {
  result = shell_exec("curl -s -S -I --max-time 10 " + shell_escape(url) + " 2>&1")
  return parse_curl_headers(result["stdout"])
}

fn http_post(url: string, body: string, content_type: string) -> any {
  ct = if content_type == "" "application/json" else content_type
  result = shell_exec("curl -s -S -L --max-time 30 " +
    "-X POST " +
    "-H 'Content-Type: " + ct + "' " +
    "-d " + shell_escape(body) + " " +
    "-w '\\n%{http_code}' " +
    shell_escape(url) + " 2>&1")
  return parse_curl_response(result)
}

fn http_put(url: string, body: string, content_type: string) -> any {
  ct = if content_type == "" "application/json" else content_type
  result = shell_exec("curl -s -S -L --max-time 30 " +
    "-X PUT " +
    "-H 'Content-Type: " + ct + "' " +
    "-d " + shell_escape(body) + " " +
    "-w '\\n%{http_code}' " +
    shell_escape(url) + " 2>&1")
  return parse_curl_response(result)
}

fn http_delete(url: string, headers: any) -> any {
  header_flags = build_header_flags(headers)
  result = shell_exec("curl -s -S -L --max-time 30 -X DELETE " +
    header_flags + " -w '\\n%{http_code}' " +
    shell_escape(url) + " 2>&1")
  return parse_curl_response(result)
}

fn http_with_auth(url: string, token: string, method: string, body: string) -> any {
  body_flag = if body == "" "" else "-d " + shell_escape(body) + " "
  result = shell_exec("curl -s -S -L --max-time 30 " +
    "-X " + method + " " +
    "-H 'Authorization: Bearer " + token + "' " +
    "-H 'Content-Type: application/json' " +
    "-H 'Accept: application/json' " +
    body_flag +
    "-w '\\n%{http_code}' " +
    shell_escape(url) + " 2>&1")
  return parse_curl_response(result)
}

fn parse_curl_response(result: any) -> any {
  stdout = result["stdout"]
  lines = str_split_lines(stdout)
  n = length(lines)

  status = 0
  body = ""

  if n > 0 {
    last_line = str_trim(lines[n - 1])
    if str_len(last_line) == 3 {
      status = str_to_int(last_line)
      body_lines = []
      i = 0
      while i < n - 1 {
        push(body_lines, lines[i])
        i = i + 1
      }
      body = str_join(body_lines, "\n")
    } else {
      body = stdout
    }
  }

  return {
    "ok": status >= 200 and status < 300,
    "status": status,
    "body": body,
    "error": if result["exit_code"] != 0 result["stderr"] else ""
  }
}

fn parse_curl_headers(raw: string) -> any {
  headers = {}
  lines = str_split_lines(raw)
  status = 0
  i = 0
  while i < length(lines) {
    line = str_trim(lines[i])
    if i == 0 {
      parts = str_split(line, " ")
      if length(parts) >= 2 { status = str_to_int(parts[1]) }
    } else {
      colon_idx = str_index_of(line, ":")
      if colon_idx > 0 {
        key = str_to_lower(str_trim(str_substr(line, 0, colon_idx)))
        val = str_trim(str_substr(line, colon_idx + 1, str_len(line)))
        headers[key] = val
      }
    }
    i = i + 1
  }
  return { "status": status, "headers": headers }
}

fn build_header_flags(headers: any) -> string {
  if headers == nil { return "" }
  result = ""
  keys = dict_keys(headers)
  i = 0
  while i < length(keys) {
    result = result + "-H " + shell_escape(keys[i] + ": " + headers[keys[i]]) + " "
    i = i + 1
  }
  return result
}

# ---- Ping / Connectivity ----

fn net_ping(host: string, count: i32, timeout_sec: i32) -> any {
  c = to_string(count)
  t = to_string(timeout_sec)
  result = shell_exec("ping -c " + c + " -W " + t + " " + shell_escape(host) + " 2>&1")
  success = result["exit_code"] == 0
  rtt_avg = parse_ping_rtt(result["stdout"])
  return {
    "ok": success,
    "host": host,
    "packets_sent": count,
    "rtt_avg_ms": rtt_avg
  }
}

fn parse_ping_rtt(output: string) -> f64 {
  if str_contains(output, "min/avg/max") {
    idx = str_index_of(output, "min/avg/max")
    rest = str_substr(output, idx, str_len(output))
    # Find the avg part
    parts = str_split(rest, "/")
    if length(parts) >= 5 {
      return str_to_float(str_trim(parts[4]))
    }
  }
  return 0.0
}

fn net_port_open(host: string, port: i32, timeout_sec: i32) -> bool {
  result = tcp_connect(host, port, timeout_sec)
  return result["ok"]
}

# ---- Network Interface Info ----

fn net_interfaces() -> array {
  result = shell_exec("ip addr show 2>/dev/null || ifconfig 2>/dev/null")
  return parse_interfaces(result["stdout"])
}

fn parse_interfaces(output: string) -> array {
  ifaces = []
  lines = str_split_lines(output)
  current = nil
  i = 0
  while i < length(lines) {
    line = lines[i]
    # Interface line: "1: eth0: <FLAGS>"
    if str_len(line) > 0 and line[0] != " " and line[0] != "\t" {
      if current != nil { push(ifaces, current) }
      parts = str_split(line, ":")
      name = if length(parts) > 1 str_trim(parts[1]) else "unknown"
      current = { "name": name, "ipv4": [], "ipv6": [], "flags": line }
    } else if current != nil {
      trimmed = str_trim(line)
      if str_starts_with(trimmed, "inet ") {
        parts = str_split(trimmed, " ")
        if length(parts) > 1 { push(current["ipv4"], str_trim(parts[1])) }
      } else if str_starts_with(trimmed, "inet6 ") {
        parts = str_split(trimmed, " ")
        if length(parts) > 1 { push(current["ipv6"], str_trim(parts[1])) }
      }
    }
    i = i + 1
  }
  if current != nil { push(ifaces, current) }
  return ifaces
}

fn net_local_ip() -> string {
  result = shell_exec("hostname -I 2>/dev/null | awk '{print $1}'")
  ip = str_trim(result["stdout"])
  if ip == "" { return "127.0.0.1" }
  return ip
}

fn net_public_ip() -> any {
  r = http_get("https://api.ipify.org")
  if r["ok"] {
    return { "ok": true, "ip": str_trim(r["body"]) }
  }
  return { "ok": false, "error": "could not get public IP" }
}

# ---- URL Utilities ----

fn url_parse(raw: string) -> any {
  scheme = ""
  host = ""
  port = 0
  path = "/"
  query = ""
  fragment = ""

  rest = raw

  # Extract scheme
  if str_contains(rest, "://") {
    idx = str_index_of(rest, "://")
    scheme = str_substr(rest, 0, idx)
    rest = str_substr(rest, idx + 3, str_len(rest))
  }

  # Extract fragment
  if str_contains(rest, "#") {
    idx = str_index_of(rest, "#")
    fragment = str_substr(rest, idx + 1, str_len(rest))
    rest = str_substr(rest, 0, idx)
  }

  # Extract query
  if str_contains(rest, "?") {
    idx = str_index_of(rest, "?")
    query = str_substr(rest, idx + 1, str_len(rest))
    rest = str_substr(rest, 0, idx)
  }

  # Extract path
  if str_contains(rest, "/") {
    idx = str_index_of(rest, "/")
    path = str_substr(rest, idx, str_len(rest))
    rest = str_substr(rest, 0, idx)
  }

  # Extract host + port
  if str_contains(rest, ":") {
    idx = str_last_index_of(rest, ":")
    port = str_to_int(str_substr(rest, idx + 1, str_len(rest)))
    host = str_substr(rest, 0, idx)
  } else {
    host = rest
    if scheme == "https" { port = 443 }
    else if scheme == "http" { port = 80 }
    else if scheme == "ftp" { port = 21 }
    else if scheme == "ssh" { port = 22 }
  }

  return {
    "scheme": scheme, "host": host, "port": port,
    "path": path, "query": query, "fragment": fragment,
    "raw": raw
  }
}

fn url_encode(s: string) -> string {
  result = shell_exec("python3 -c 'import urllib.parse,sys; print(urllib.parse.quote(sys.stdin.read().rstrip()))' <<< " + shell_escape(s))
  return str_trim(result["stdout"])
}

fn url_decode(s: string) -> string {
  result = shell_exec("python3 -c 'import urllib.parse,sys; print(urllib.parse.unquote(sys.stdin.read().rstrip()))' <<< " + shell_escape(s))
  return str_trim(result["stdout"])
}

fn url_build(scheme: string, host: string, port: i32, path: string, query: any) -> string {
  url = scheme + "://" + host
  default_port = (scheme == "https" and port == 443) or (scheme == "http" and port == 80)
  if not default_port and port > 0 {
    url = url + ":" + to_string(port)
  }
  url = url + path
  if query != nil {
    keys = dict_keys(query)
    if length(keys) > 0 {
      url = url + "?"
      i = 0
      while i < length(keys) {
        if i > 0 { url = url + "&" }
        url = url + url_encode(keys[i]) + "=" + url_encode(query[keys[i]])
        i = i + 1
      }
    }
  }
  return url
}

# ---- Shell Helpers ----

fn shell_escape(s: string) -> string {
  return "'" + str_replace(s, "'", "'\\''") + "'"
}

fn shell_exec(cmd: string) -> any {
  # This maps to the runtime's exec primitive
  return exec_command(cmd)
}

fn net_stats_report(conn_count: i32, bytes_sent: i32, bytes_recv: i32) -> string {
  out = "=== Network Stats ===\n"
  out = out + "Connections:  " + to_string(conn_count) + "\n"
  out = out + "Bytes sent:   " + to_string(bytes_sent) + "\n"
  out = out + "Bytes recv:   " + to_string(bytes_recv) + "\n"
  return out
}

